
(function(){
'use strict';

/* ===================== 配置区 ===================== */
/* 和弦库：在此增删和弦即可。
   frets   低E→高e 共6弦：-1=闷音X，0=空弦，>0=品格数
   fingers 对应每根弦的按弦手指（0=不按），仅用于指法图标注
   barre   横按（可选）：{fret:品数, from:起始弦序号, to:结束弦序号} */
const CHORDS = [
  { name:'C',   frets:[-1, 3, 2, 0, 1, 0], fingers:[0, 3, 2, 0, 1, 0] },
  { name:'D',   frets:[-1,-1, 0, 2, 3, 2], fingers:[0, 0, 0, 1, 3, 2] },
  { name:'E',   frets:[ 0, 2, 2, 1, 0, 0], fingers:[0, 2, 3, 1, 0, 0] },
  { name:'F',   frets:[ 1, 3, 3, 2, 1, 1], fingers:[1, 3, 4, 2, 1, 1], barre:{fret:1, from:0, to:5} },
  { name:'G',   frets:[ 3, 2, 0, 0, 0, 3], fingers:[3, 2, 0, 0, 0, 4] },
  { name:'A',   frets:[-1, 0, 2, 2, 2, 0], fingers:[0, 0, 1, 2, 3, 0] },
  { name:'B',   frets:[-1, 2, 4, 4, 4, 2], fingers:[0, 1, 3, 4, 2, 1], barre:{fret:2, from:1, to:5} },
  { name:'Am',  frets:[-1, 0, 2, 2, 1, 0], fingers:[0, 0, 2, 3, 1, 0] },
  { name:'Dm',  frets:[-1,-1, 0, 2, 3, 1], fingers:[0, 0, 0, 2, 3, 1] },
  { name:'Em',  frets:[ 0, 2, 2, 0, 0, 0], fingers:[0, 2, 3, 0, 0, 0] },
  { name:'C7',  frets:[-1, 3, 2, 3, 1, 0], fingers:[0, 3, 2, 4, 1, 0] },
  { name:'D7',  frets:[-1,-1, 0, 2, 1, 2], fingers:[0, 0, 0, 2, 1, 3] },
  { name:'D9',  frets:[-1, 5, 4, 5, 5, 5], fingers:[0, 1, 2, 1, 1, 1] },
  { name:'E7',  frets:[ 0, 2, 0, 1, 0, 0], fingers:[0, 2, 0, 1, 0, 0] },
  { name:'G7',  frets:[ 3, 2, 0, 0, 0, 1], fingers:[3, 2, 0, 0, 0, 1] },
  { name:'A7',  frets:[-1, 0, 2, 0, 2, 0], fingers:[0, 0, 1, 0, 2, 0] },
  { name:'B7',  frets:[-1, 2, 1, 2, 0, 2], fingers:[0, 2, 1, 3, 0, 4] },
  { name:'Cmaj7',frets:[-1, 3, 2, 0, 0, 0], fingers:[0, 3, 2, 0, 0, 0] },
  { name:'Fmaj7',frets:[-1,-1, 3, 2, 1, 0], fingers:[0, 0, 3, 2, 1, 0] },
  { name:'Am7', frets:[-1, 0, 2, 0, 1, 0], fingers:[0, 0, 2, 0, 1, 0] },
  { name:'Dm7', frets:[-1,-1, 0, 2, 1, 1], fingers:[0, 0, 0, 3, 1, 2] },
  { name:'Em7', frets:[ 0, 2, 0, 0, 0, 0], fingers:[0, 2, 0, 0, 0, 0] }
];

const CHORD_MAP = {};
CHORDS.forEach(function(c){ CHORD_MAP[c.name] = c; });
/* 休止占位（练歌时用于休止小节 / 调整和弦节奏）：可正常选中、进序列，播放时不发声 */
const REST_CHORD = { name:'⌀', rest:true };
CHORD_MAP['⌀'] = REST_CHORD;

/* 扫弦：固定全下扫，每拍一次，拍数由"拍数"设置控制（1–16） */
const BPM_MIN = 20, BPM_MAX = 200, BPM_STEP = 5;
const OPEN_FREQS = [82.41, 110.00, 146.83, 196.00, 246.94, 329.63];

/* 真实吉他扫弦采样（Freesound，SpeedY 尼龙吉他 CC0，可开源）：有采样直接播放录音，
   含 F（SpeedY Bar Chord Style，同琴同录音）；B/C7/G7/Fmaj7/Am7/Dm7/Em7 与新增
   自定义和弦走合成兜底（无版权问题，可推 GitHub） */
const CHORD_SAMPLES = {
  C: 'data:audio/mpeg;base64,',
  D: 'data:audio/mpeg;base64,',
  E: 'data:audio/mpeg;base64,',
  G: 'data:audio/mpeg;base64,',
  A: 'data:audio/mpeg;base64,',
  Am: 'data:audio/mpeg;base64,',
  Dm: 'data:audio/mpeg;base64,',
  Em: 'data:audio/mpeg;base64,',
  'A7': 'data:audio/mpeg;base64,',
  'B7': 'data:audio/mpeg;base64,',
  'D7': 'data:audio/mpeg;base64,',
  'E7': 'data:audio/mpeg;base64,',
F: 'data:audio/mpeg;base64,',
};
/* ===================== 状态 ===================== */
/* 播放序列：双行轮流。行 = 连续序列每 ROW_LEN 个切一段；当前行播完 → 上滑淡出 → 下行递补 */
const ROW_LEN = 6;                  /* 每行序列数量（暂定 6，可调） */
const BEATS_MIN = 1, BEATS_MAX = 16;
const state = {
  bpm: 60,
  beats: 4,             /* 每和弦拍数（1–16） */
  pendingBeats: null,   /* 播放中修改拍数时，留到下一和弦才切换 */
  preview: true,
  random: false,
  selected: ['C','Dm','Em','F','G','Am'],  /* 默认选中 */
  multi: false,         /* 多选：同一和弦可否重复选中（默认关） */
  autoHideList: true,   /* 开始播放后自动隐藏和弦列表 */
  autoHideSet: false,   /* 开始播放后自动隐藏设置面板 */
  active: false,
  paused: false,        /* 暂停态（视频播放器式：空格暂停/继续，Esc/回车退出） */
  pauseElapsed: 0,      /* 暂停时当前和弦已播时长 ms */
  chordStart: 0,
  dwell: 0,             /* 当前和弦时长 ms */
  rowStart: 0,          /* 当前行在连续序列中的起始下标 */
  rowIdx: 0,            /* 当前行内播到第几个（0 基） */
  curRow: [],           /* 当前行（和弦对象数组） */
  nextRow: [],          /* 下一行 */
  nextRow2: [],         /* 下下行（换行时补入） */
  curRowEl: null,       /* 当前行 DOM */
  nextRowEl: null,      /* 下一行 DOM */
  shiftBusy: false,     /* 换行动画进行中 */
  raf: 0,
  beatIndex: -1,
  timeouts: new Set(),  /* 待触发的声音定时器 */
  audio: null,
  master: null,
  sampleBus: null
};
let passCache = [];     /* 随机模式：已生成的和弦对象流 */

/* ===================== DOM ===================== */
const root = document.getElementById('app');
const leftPanel = document.getElementById('leftPanel');
const rightPanel = document.getElementById('rightPanel');
const chordList = document.getElementById('chordList');
const leftSub = document.getElementById('leftSub');
const sumChips = document.getElementById('sumChips');
const sumEmpty = document.getElementById('sumEmpty');
const clearBtn = document.getElementById('clearBtn');
const multiSwitch = document.getElementById('multiSwitch');
const bpmVal = document.getElementById('bpmVal');
const bpmUp = document.getElementById('bpmUp');
const bpmDown = document.getElementById('bpmDown');
const beatVal = document.getElementById('beatVal');
const beatSub = document.getElementById('beatSub');
const beatUp = document.getElementById('beatUp');
const beatDown = document.getElementById('beatDown');
const previewSwitch = document.getElementById('previewSwitch');
const randomSwitch = document.getElementById('randomSwitch');
const hideListSwitch = document.getElementById('hideListSwitch');
const hideSetSwitch = document.getElementById('hideSetSwitch');
const stopRound = document.getElementById('stopRound');
const toast = document.getElementById('toast');
const chordBlock = document.getElementById('chordBlock');
const rowStack = document.getElementById('rowStack');
const beatDots = document.getElementById('beatDots');

/* ===================== 和弦图绘制（SVG） ===================== */
const VB_W = 120, VB_H = 150;
const PAD_L = 16, PAD_R = 8, TOP_H = 28, FRET_H = 29, STR_Y0 = 28, STR_Y1 = 144;
const STR_COLOR = '#CFC4AE', FRET_COLOR = 'rgba(207,196,174,.32)';
/* 语义：琥珀=按弦动作，中性灰=弦状态（闷音 X / 空弦 O / 休止）。危险色只留给"停止" */
const DOT_COLOR = '#E8A33D', MUTE_COLOR = '#998D75', OPEN_COLOR = '#9A8F77';

function stringX(i){ return PAD_L + i * (VB_W - PAD_L - PAD_R) / 5; }

function chordSVG(chord){
  if (chord.rest) {
    return '<svg viewBox="0 0 ' + VB_W + ' ' + VB_H + '" role="img" aria-label="休止占位" xmlns="http://www.w3.org/2000/svg">' +
      '<circle cx="' + (VB_W/2) + '" cy="78" r="44" fill="none" stroke="' + MUTE_COLOR + '" stroke-width="3" stroke-dasharray="5 7"/>' +
      '<text x="' + (VB_W/2) + '" y="92" text-anchor="middle" font-size="42" font-weight="700" fill="' + MUTE_COLOR + '">⌀</text>' +
      '<text x="' + (VB_W/2) + '" y="128" text-anchor="middle" font-size="12" fill="' + OPEN_COLOR + '">休止</text></svg>';
  }
  const frets = chord.frets;
  /* 统一从第 1 品（琴枕）开始画，方便对照实际琴颈 */
  const base = 1;
  const parts = [];
  /* 品丝横线（4 品） */
  for (let r = 0; r <= 4; r++) {
    const y = STR_Y0 + r * FRET_H;
    parts.push('<line x1="' + PAD_L + '" y1="' + y + '" x2="' + (VB_W - PAD_R) + '" y2="' + y + '" stroke="' + FRET_COLOR + '" stroke-width="1"/>');
  }
  /* 琴弦 */
  for (let i = 0; i < 6; i++) {
    parts.push('<line x1="' + stringX(i) + '" y1="' + STR_Y0 + '" x2="' + stringX(i) + '" y2="' + STR_Y1 + '" stroke="' + STR_COLOR + '" stroke-width="1.7"/>');
  }
  /* 上琴枕（始终从第 1 品开始） */
  parts.push('<rect x="' + PAD_L + '" y="25.5" width="' + (VB_W - PAD_L - PAD_R) + '" height="4" rx="1.6" fill="' + STR_COLOR + '"/>');
  /* 闷音 X / 空弦 O */
  for (let i = 0; i < 6; i++) {
    const x = stringX(i);
    if (frets[i] < 0) {
      parts.push('<line x1="' + (x - 4.6) + '" y1="9.4" x2="' + (x + 4.6) + '" y2="18.6" stroke="' + MUTE_COLOR + '" stroke-width="1.9" stroke-linecap="round"/>');
      parts.push('<line x1="' + (x - 4.6) + '" y1="18.6" x2="' + (x + 4.6) + '" y2="9.4" stroke="' + MUTE_COLOR + '" stroke-width="1.9" stroke-linecap="round"/>');
    } else if (frets[i] === 0) {
      parts.push('<circle cx="' + x + '" cy="14" r="4.4" fill="none" stroke="' + OPEN_COLOR + '" stroke-width="1.7"/>');
    }
  }
  /* 横按 */
  if (chord.barre) {
    const b = chord.barre;
    const y = STR_Y0 + (b.fret - base + 0.5) * FRET_H;
    const x1 = stringX(b.from), x2 = stringX(b.to);
    parts.push('<rect x="' + x1 + '" y="' + (y - 7) + '" width="' + (x2 - x1) + '" height="14" rx="7" fill="' + DOT_COLOR + '"/>');
    parts.push('<text x="' + (x1 + 8) + '" y="' + (y + 4) + '" text-anchor="middle" font-size="11" font-weight="700" fill="#16130C">1</text>');
  }
  /* 指位圆点 + 手指号 */
  for (let i = 0; i < 6; i++) {
    const f = frets[i];
    if (f <= 0) continue;
    if (chord.barre && f === chord.barre.fret && i >= chord.barre.from && i <= chord.barre.to) continue;
    const y = STR_Y0 + (f - base + 0.5) * FRET_H;
    parts.push('<circle cx="' + stringX(i) + '" cy="' + y + '" r="7" fill="' + DOT_COLOR + '"/>');
    parts.push('<text x="' + stringX(i) + '" y="' + (y + 3.6) + '" text-anchor="middle" font-size="10.5" font-weight="700" fill="#16130C">' + chord.fingers[i] + '</text>');
  }
  return '<svg viewBox="0 0 ' + VB_W + ' ' + VB_H + '" role="img" aria-label="' + chord.name + ' 和弦指法图" xmlns="http://www.w3.org/2000/svg">' + parts.join('') + '</svg>';
}

/* ===================== 左栏渲染 ===================== */
function renderLeft(){
  leftSub.textContent = state.multi
    ? '点击多选 · 选中按顺序播放'
    : '点击切换选中 · 同一和弦只保留一次';
  const st = chordList.scrollTop;
  chordList.innerHTML = [REST_CHORD].concat(CHORDS).map(function(chord){
    const cnt = state.selected.filter(function(n){ return n === chord.name; }).length;
    const sel = cnt > 0 ? ' selected' : '';
    /* 右下角角标显示重复次数（≥2 才显示）；顺序见摘要条 chips */
    const badge = cnt > 1 ? '<span class="order-badge">×' + cnt + '</span>' : '';
    const restTag = chord.rest ? '<span class="rest-badge">休止</span>' : '';
    return '<div class="chord-card' + sel + (chord.rest ? ' rest-card' : '') + '" data-name="' + chord.name + '" role="button" aria-pressed="' + (cnt > 0 ? 'true' : 'false') + '" tabindex="0">' +
      chordSVG(chord) +
      '<div class="card-name">' + chord.name + '</div>' + badge + restTag + '</div>';
  }).join('');
  chordList.scrollTop = st;
  renderSummary();
}
function renderSummary(){
  if (!state.selected.length) {
    sumEmpty.style.display = '';
    sumChips.innerHTML = '';
    return;
  }
  sumEmpty.style.display = 'none';
  sumChips.innerHTML = state.selected.map(function(name, i){
    return '<span class="sum-chip" data-i="' + i + '" role="button" tabindex="0" title="点击移除这一次"><b>' + (i + 1) + '</b>' + name + '<i class="chip-x">✕</i></span>';
  }).join('');
}
/* 点卡片：开多选 = 追加（可重复）；关多选 = 切换选中（同一和弦只保留一次） */
function appendSelect(name){
  if (state.multi) {
    state.selected.push(name);
  } else {
    const i = state.selected.indexOf(name);
    if (i >= 0) state.selected.splice(i, 1);
    else state.selected.push(name);
  }
  renderLeft();
  if (state.active) { refreshFutureRows(); } else { renderStandby(); }
}

/* ===================== 右栏渲染 ===================== */
function renderRight(){
  bpmVal.textContent = state.bpm;
  beatVal.textContent = state.pendingBeats === null ? state.beats : state.pendingBeats;
  beatSub.textContent = state.pendingBeats === null
    ? '每和弦停留拍数（1–16）· 下一和弦生效'
    : '下一和弦将改为 ' + state.pendingBeats + ' 拍';
  previewSwitch.setAttribute('aria-checked', state.preview ? 'true' : 'false');
  randomSwitch.setAttribute('aria-checked', state.random ? 'true' : 'false');
  hideListSwitch.setAttribute('aria-checked', state.autoHideList ? 'true' : 'false');
  hideSetSwitch.setAttribute('aria-checked', state.autoHideSet ? 'true' : 'false');
  multiSwitch.setAttribute('aria-checked', state.multi ? 'true' : 'false');
}

/* ===================== 音频（真实采样 + 合成兜底） ===================== */
const sampleCache = {};
const sampleLoads = {};
function ensureAudio(){
  if (!state.audio) {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = new AC();
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -14;
    comp.knee.value = 22;
    comp.ratio.value = 5;
    comp.attack.value = 0.003;
    comp.release.value = 0.22;
    const sampleBus = ctx.createGain();
    sampleBus.gain.value = 0.9;
    sampleBus.connect(comp);
    comp.connect(ctx.destination);
    state.audio = ctx;
    state.master = comp;
    state.sampleBus = sampleBus;
  }
  if (state.audio.state === 'suspended') state.audio.resume();
}
/* 解码采样（首次使用；失败静默回退合成） */
function loadSample(name, cb){
  const data = CHORD_SAMPLES[name];
  if (!data) { if (cb) cb(null); return; }
  if (sampleCache[name]) { if (cb) cb(sampleCache[name]); return; }
  if (!sampleLoads[name]) {
    sampleLoads[name] = fetch(data).then(function(r){ return r.arrayBuffer(); }).then(function(buf){
      return state.audio.decodeAudioData(buf);
    }).then(function(ab){
      sampleCache[name] = ab;
      return ab;
    }).catch(function(){ return null; });
    sampleLoads[name].then(function(){ delete sampleLoads[name]; });
  }
  if (cb) sampleLoads[name].then(cb);
}
/* 播放一次真实下扫采样 */
function playSample(buf, t, vol){
  if (!buf) return;
  const src = state.audio.createBufferSource();
  src.buffer = buf;
  const g = state.audio.createGain();
  g.gain.value = (vol === undefined) ? 0.9 : vol;
  src.connect(g); g.connect(state.sampleBus);
  src.start(t);
}
/* 节拍器咔嚓声（预览关闭时使用）：短促高频 click，每和弦首拍重音 */
function metronomeClick(t, accent){
  const ctx = state.audio;
  const o = ctx.createOscillator();
  const g = ctx.createGain();
  o.type = 'triangle';
  o.frequency.value = accent ? 1650 : 1180;
  g.gain.setValueAtTime(accent ? 0.22 : 0.14, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + 0.028);
  o.connect(g); g.connect(state.master);
  o.start(t); o.stop(t + 0.05);
}
/* 合成兜底（仅用于暂无采样的和弦） */
function pluck(freq, t, vol){
  const ctx = state.audio;
  const gain = ctx.createGain();
  gain.connect(state.master);
  gain.gain.setValueAtTime(0.0001, t);
  gain.gain.exponentialRampToValueAtTime(vol, t + 0.006);
  gain.gain.exponentialRampToValueAtTime(0.0001, t + 1.15);
  const filt = ctx.createBiquadFilter();
  filt.type = 'lowpass';
  filt.frequency.setValueAtTime(2400, t);
  filt.frequency.exponentialRampToValueAtTime(900, t + 0.9);
  filt.Q.value = 0.8;
  filt.connect(gain);
  const o1 = ctx.createOscillator();
  o1.type = 'sawtooth';
  o1.frequency.value = freq;
  const g1 = ctx.createGain();
  g1.gain.value = 0.5;
  o1.connect(g1); g1.connect(filt);
  o1.start(t); o1.stop(t + 1.2);
  const o2 = ctx.createOscillator();
  o2.type = 'triangle';
  o2.frequency.value = freq * 2;
  const g2 = ctx.createGain();
  g2.gain.value = 0.26;
  o2.connect(g2); g2.connect(filt);
  o2.start(t); o2.stop(t + 0.7);
  const o3 = ctx.createOscillator();
  o3.type = 'triangle';
  o3.frequency.value = freq * 3;
  const g3 = ctx.createGain();
  g3.gain.value = 0.1;
  o3.connect(g3); g3.connect(filt);
  o3.start(t); o3.stop(t + 0.45);
}
/* 按当前扫弦节奏的拍点扫弦；有采样播真实录音，无采样用合成兜底 */
/* 构造一次扫弦的触发函数（strumChord 与暂停后 resume 共用） */
function clearAudioTimers(){
  state.timeouts.forEach(function(id){ clearTimeout(id); });
  state.timeouts.clear();
}
function scheduleAudio(fn, delay){
  const id = setTimeout(function(){
    state.timeouts.delete(id);
    fn();
  }, delay);
  state.timeouts.add(id);
  return id;
}
function makeFire(chord, dir, k){
  return function(){
      if (!state.audio) return;
      const t0 = state.audio.currentTime + 0.01;
      if (!state.preview) {
        /* 节拍器模式：每拍一声咔嚓（休止也响，便于数拍） */
        metronomeClick(t0, k === 0);
        return;
      }
      if (chord.rest) return;   /* 预览开时休止占位不发声 */
      if (CHORD_SAMPLES[chord.name]) {
        const ab = sampleCache[chord.name];
        if (ab) {
          playSample(ab, t0, k === 0 ? 0.98 : 0.78); /* 每个和弦首拍更清楚 */
        } else {
          /* 采样尚未解码：解码完成后立即补播（同和弦后续轮次用缓存） */
          loadSample(chord.name, function(decoded){
            if (decoded) playSample(decoded, state.audio.currentTime + 0.01, k === 0 ? 0.98 : 0.78);
          });
        }
        return;
      }
      /* 合成兜底：近实时顺序弹拨（14ms 间隔在秒级挂起窗口内，安全） */
      const order = dir === 'down' ? [0, 1, 2, 3, 4, 5] : [5, 4, 3, 2, 1, 0];
      let idx = 0;
      order.forEach(function(s){
        if (chord.frets[s] < 0) return;
        const freq = OPEN_FREQS[s] * Math.pow(2, Math.max(0, chord.frets[s]) / 12);
        pluck(freq, t0 + idx * 0.014, k === 0 ? 0.38 : 0.29);
        idx++;
      });
  };
}

function strumChord(chord){
  if (!state.audio) return;
  /* 每拍一次全下扫（拍数由"拍数"设置控制）。
     第 1 拍与切换同步（下拍点），扫弦节奏与画面一致、不提前。
     用 setTimeout 在到点瞬间创建节点近实时播放：不在未来很远的时刻预排音频，
     避免部分手机浏览器（音频引擎挂起/中断时）丢弃已排期的未来事件 */
  const beatMs = 60000 / state.bpm;
  for (let k = 0; k < state.beats; k++) {
    const at = Math.round(k * beatMs);
    scheduleAudio(makeFire(chord, 'down', k), at);
  }
}

/* 可视节拍：第一点与每个和弦的首拍同步。 */
function renderBeatDots(){
  beatDots.innerHTML = Array.from({length:state.beats}, function(_, i){
    return '<i class="beat-dot" data-beat="' + i + '"></i>';
  }).join('');
  state.beatIndex = -1;
  updateBeatIndicator(0);
}
function updateBeatIndicator(index){
  if (!beatDots.children.length) return;
  const next = Math.max(0, Math.min(state.beats - 1, index));
  if (state.beatIndex === next) return;
  state.beatIndex = next;
  Array.prototype.forEach.call(beatDots.children, function(dot, i){
    dot.classList.toggle('active', i === next);
  });
  beatDots.setAttribute('aria-label', '第 ' + (next + 1) + ' 拍，共 ' + state.beats + ' 拍');
}

/* ===================== 播放循环（双行序列，按行轮流播出） ===================== */
/* 连续序列：按顺序 = 选中列表循环；随机 = 逐轮洗牌拼接。
   行 = 连续序列每 ROW_LEN 个切一段；当前行播完 → 旧行吹散上滑 → 下一行平滑递补，
   同时下下行补入底栏；整体按行轮流。 */
function shuffleArr(arr){
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const t = a[i]; a[i] = a[j]; a[j] = t;
  }
  return a;
}
function chordAt(absIdx){
  const sel = state.selected;
  if (!sel.length) return null;
  if (!state.random) return CHORD_MAP[sel[absIdx % sel.length]];
  while (passCache.length <= absIdx) {
    passCache = passCache.concat(shuffleArr(sel.map(function(n){ return CHORD_MAP[n]; })));
  }
  return passCache[absIdx];
}
function rowAt(absIdx){
  const row = [];
  for (let k = 0; k < ROW_LEN; k++) row.push(chordAt(absIdx + k));
  return row;
}
function beatDwell(){
  return state.beats * 60000 / state.bpm;
}
function setBeats(next){
  if (state.active) {
    state.pendingBeats = next;
  } else {
    state.beats = next;
    state.pendingBeats = null;
  }
  renderRight();
}
function applyPendingBeats(){
  if (state.pendingBeats === null) return;
  state.beats = state.pendingBeats;
  state.pendingBeats = null;
  renderRight();
  renderBeatDots();
}
function renderRowEl(row, opts){
  const el = document.createElement('div');
  el.className = 'seq-row' + (opts.weak ? ' weak' : '');
  row.forEach(function(chord, i){
    const cell = document.createElement('div');
    cell.className = 'seq-cell' + (opts.activeIdx === i ? ' active' : '');
    cell.innerHTML = '<div class="seq-cell-svg">' + chordSVG(chord) + '</div>' +
      '<div class="seq-cell-name">' + chord.name + '</div>';
    el.appendChild(cell);
  });
  return el;
}
function rebuildRows(){
  rowStack.classList.remove('shifting');
  rowStack.style.transform = '';
  rowStack.style.height = '';
  rowStack.innerHTML = '';
  state.curRowEl = renderRowEl(state.curRow, { activeIdx: state.rowIdx });
  state.nextRowEl = renderRowEl(state.nextRow, { weak:true });
  rowStack.append(state.curRowEl, state.nextRowEl);
}
function updateCellActive(){
  if (!state.curRowEl) return;
  const cells = state.curRowEl.querySelectorAll('.seq-cell');
  cells.forEach(function(c, i){ c.classList.toggle('active', i === state.rowIdx); });
}
/* 换行：旧行上滑淡出，下一行平滑递补，下下行补入底栏。
   全程锁定整列高度（3 行瞬时态不改变外部布局），结束时同步复位 transform
   与高度，无"推上去又回落"感 */
function shiftRows(){
  if (!state.active) return;
  const stack = rowStack;
  const leaving = stack.firstElementChild;
  if (!leaving) return;
  state.shiftBusy = true;
  const rising = leaving.nextElementSibling;
  if (!rising) return;
  /* 下行转为当前行：去弱化 + 高亮第 1 格（同步更新引用，期间 tick 高亮不落空） */
  rising.classList.remove('weak');
  const first = rising.querySelector('.seq-cell');
  if (first) first.classList.add('active');
  state.curRowEl = rising;
  /* 锁定整列高度（当前 2 行），补入下下行（弱化） */
  stack.style.height = stack.offsetHeight + 'px';
  state.nextRow2 = rowAt(state.rowStart + ROW_LEN * 2);
  const incoming = renderRowEl(state.nextRow2, { weak:true });
  stack.appendChild(incoming);
  state.nextRowEl = incoming;
  /* 旧行淡出 + 整列上滑一行（平滑递补） */
  leaving.classList.add('leaving');
  const gap = parseFloat(getComputedStyle(stack).gap) || 22;
  const dy = -(leaving.offsetHeight + gap);
  stack.classList.add('shifting');
  stack.style.transform = 'translateY(' + dy + 'px)';
  setTimeout(function(){
    if (!state.active || !state.shiftBusy) return;
    leaving.remove();
    stack.classList.remove('shifting');
    stack.style.transform = '';
    stack.style.height = '';
    state.shiftBusy = false;
  }, 580);
}
/* 热加载：播放中改选择和弦/随机，当前行继续，后续行按新选择即时重排 */
function refreshFutureRows(){
  if (!state.selected.length) {
    stop();
    showToast('已清空全部和弦，停止播放');
    return;
  }
  if (state.random) passCache = [];
  state.nextRow = rowAt(state.rowStart + ROW_LEN);
  state.nextRow2 = rowAt(state.rowStart + ROW_LEN * 2);
  if (state.nextRowEl && state.nextRowEl.parentNode) {
    const el = renderRowEl(state.nextRow, { weak:true });
    state.nextRowEl.replaceWith(el);
    state.nextRowEl = el;
  }
}
function advance(now){
  applyPendingBeats();
  if (state.rowIdx + 1 < state.curRow.length) {
    /* 行内前进：高亮移到下一格 */
    state.rowIdx++;
    state.chordStart = now;
    state.dwell = beatDwell();
    updateBeatIndicator(0);
    updateCellActive();
    strumChord(state.curRow[state.rowIdx]);
  } else {
    /* 本行播完：进入下一行（状态同步切换，视觉交给 shiftRows） */
    state.rowStart += ROW_LEN;
    state.rowIdx = 0;
    state.curRow = state.nextRow;
    state.nextRow = state.nextRow2;
    state.nextRow2 = rowAt(state.rowStart + ROW_LEN * 2);
    state.chordStart = now;
    state.dwell = beatDwell();
    updateBeatIndicator(0);
    strumChord(state.curRow[0]);
    shiftRows();
  }
}
function tick(now){
  if (!state.active) return;
  const el = now - state.chordStart;
  const d = state.dwell;
  if (el >= d) {
    advance(now);
    state.raf = requestAnimationFrame(tick);
    return;
  }
  updateBeatIndicator(Math.floor(el / (60000 / state.bpm)));
  state.raf = requestAnimationFrame(tick);
}
/* 桌面端：按"自动隐藏"配置收/放面板（移动端独立页由 start 关闭） */
function applyPanelAutoHide(running){
  if (window.matchMedia('(max-width:1180px)').matches) return;
  leftPanel.classList.toggle('hide-running', running && state.autoHideList);
  rightPanel.classList.toggle('hide-running', running && state.autoHideSet);
}
function preparePractice(){
  ensureAudio();
  if (state.random) passCache = [];
  state.rowStart = 0;
  state.rowIdx = 0;
  state.curRow = rowAt(0);
  state.nextRow = rowAt(ROW_LEN);
  state.nextRow2 = rowAt(ROW_LEN * 2);
  state.dwell = beatDwell();
  /* 同一和弦的并发解码会被 loadSample 合并，避免首次点击挤占主线程。 */
  if (state.preview) {
    state.curRow.concat(state.nextRow).forEach(function(c){
      if (CHORD_SAMPLES[c.name]) loadSample(c.name);
    });
  }
  rebuildRows();
  renderBeatDots();
}
function beginPractice(){
  state.active = true;
  state.paused = false;
  state.chordStart = performance.now();
  state.dwell = beatDwell();
  root.classList.add('running');
  updateBeatIndicator(0);
  updateMobilePlayBtn();
  strumChord(state.curRow[0]);
  state.raf = requestAnimationFrame(tick);
}
function start(){
  if (!state.selected.length) {
    showToast('请先至少选择一个和弦');
    return;
  }
  preparePractice();
  leftPanel.classList.remove('show');
  rightPanel.classList.remove('show');
  syncSheets();
  applyPanelAutoHide(true);
  beginPractice();
}
function stop(){
  state.active = false;
  state.paused = false;
  state.shiftBusy = false;
  root.classList.remove('paused');
  cancelAnimationFrame(state.raf);
  clearAudioTimers();
  rowStack.classList.remove('shifting');
  rowStack.style.transform = '';
  rowStack.style.height = '';
  rowStack.innerHTML = '';
  root.classList.remove('running');
  if (webLandscape) exitWebLandscape();
  applyPanelAutoHide(false);
  renderStandby();
}
/* 暂停：停表定格当前和弦（已响扫弦自然衰减），保留播放状态 */
function pause(){
  if (!state.active || state.paused) return;
  state.paused = true;
  state.pauseElapsed = performance.now() - state.chordStart;
  cancelAnimationFrame(state.raf);
  clearAudioTimers();
  root.classList.add('paused');
  updateMobilePlayBtn();
}
/* 继续：从暂停点恢复当前和弦（剩余扫弦重新按剩余时间排程，计时从暂停点续走） */
function resume(){
  if (!state.active || !state.paused) return;
  state.paused = false;
  const el = state.pauseElapsed;
  state.chordStart = performance.now() - el;
  if (state.audio) {
    const chord = state.curRow[state.rowIdx];
    const beatMs = 60000 / state.bpm;
    for (let k = 0; k < state.beats; k++) {
      const at = k * beatMs;
      if (at <= el + 1) continue;   /* 已响过的动作不重播 */
      scheduleAudio(makeFire(chord, 'down', k), Math.round(at - el));
    }
  }
  root.classList.remove('paused');
  updateMobilePlayBtn();
  state.raf = requestAnimationFrame(tick);
}
function togglePractice(){
  if (!state.active) start();
  else if (state.paused) resume();
  else pause();
}
/* 紧凑布局主控：开始 ⇄ 暂停 ⇄ 继续。 */
function updateMobilePlayBtn(){
  if (!mPlayBtn) return;
  const playing = state.active && !state.paused;
  const label = playing ? '暂停' : (state.paused ? '继续' : '开始');
  const icon = playing
    ? '<svg class="m-play-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6.5 5h4v14h-4zM13.5 5h4v14h-4z" fill="currentColor"/></svg>'
    : '<svg class="m-play-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14l11-7z" fill="currentColor"/></svg>';
  mPlayBtn.innerHTML = icon + '<span class="m-play-label">' + label + '</span>';
  mPlayBtn.setAttribute('aria-label', playing ? '暂停练习' : (state.paused ? '继续练习' : '开始练习'));
  updateLandscapeLayout();
}
/* 未播放时：直接展示两行和弦序列预览（初始状态，全端生效） */
function renderStandby(){
  if (state.active) return;
  updateMobilePlayBtn();
  if (!state.selected.length) {
    rowStack.innerHTML = '';
    beatDots.innerHTML = '';
    return;
  }
  state.rowStart = 0;
  state.rowIdx = 0;
  state.curRow = rowAt(0);
  state.nextRow = rowAt(ROW_LEN);
  rowStack.classList.remove('shifting');
  rowStack.style.transform = '';
  rowStack.style.height = '';
  rowStack.innerHTML = '';
  rowStack.append(renderRowEl(state.curRow, {}), renderRowEl(state.nextRow, { weak:true }));
  beatDots.innerHTML = '';
}
/* ===================== 提示 ===================== */
let toastTimer = 0;
function showToast(msg){
  toast.textContent = msg;
  toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(function(){ toast.classList.remove('show'); }, 1700);
}

/* ===================== 事件与焦点管理 ===================== */
/* 捐赠弹层：当前页面展示收款码（不跳转新页） */
const donateMask = document.getElementById('donateMask');
const donateOpen = document.getElementById('donateOpen');
const donateClose = document.getElementById('donateClose');
let donateOpener = null;
function closeDonate(){
  donateMask.classList.remove('show');
  if (donateOpener && document.contains(donateOpener)) donateOpener.focus();
  donateOpener = null;
}
donateOpen.addEventListener('click', function(e){
  e.preventDefault();
  donateOpener = e.currentTarget;
  donateMask.classList.add('show');
  requestAnimationFrame(function(){ donateClose.focus(); });
});
donateClose.addEventListener('click', closeDonate);
donateMask.addEventListener('click', function(e){
  if (e.target === donateMask) closeDonate();
});
/* 紧凑布局：选择和弦 / 设置以底部弹层呈现。 */
const settingsOpen = document.getElementById('settingsOpen');
const settingsClose = document.getElementById('settingsClose');
const chordClose = document.getElementById('chordClose');
const sheetScrim = document.getElementById('sheetScrim');
const mChordOpen = document.getElementById('mChordOpen');
const mPlayBtn = document.getElementById('mPlayBtn');
const mSetOpen = document.getElementById('mSetOpen');
const mLandscapeBtn = document.getElementById('mLandscapeBtn');
const mLandscapeExit = document.getElementById('mLandscapeExit');
let webLandscape = false;

function updateLandscapeLayout(){
  if (!mLandscapeBtn) return;
  const layoutLandscape = webLandscape || window.matchMedia('(orientation:landscape)').matches;
  root.classList.toggle('web-landscape', webLandscape);
  root.classList.toggle('landscape-layout', layoutLandscape);
  document.body.classList.toggle('web-landscape-active', webLandscape);
}
function exitWebLandscape(){
  webLandscape = false;
  updateLandscapeLayout();
}
function enterWebLandscape(){
  if (window.matchMedia('(orientation:landscape)').matches) return;
  webLandscape = true;
  updateLandscapeLayout();
}
function exitLandscape(){
  if (state.active && !state.paused) pause();
  if (webLandscape) {
    exitWebLandscape();
    return;
  }
  const orientation = window.screen && window.screen.orientation;
  if (orientation && typeof orientation.lock === 'function') {
    try {
      Promise.resolve(orientation.lock('portrait')).catch(function(){
        showToast('已暂停，请旋转手机恢复竖屏');
      });
    } catch (err) {
      showToast('已暂停，请旋转手机恢复竖屏');
    }
  } else {
    showToast('已暂停，请旋转手机恢复竖屏');
  }
}
window.addEventListener('orientationchange', function(){
  if (webLandscape && window.matchMedia('(orientation:landscape)').matches) webLandscape = false;
  updateLandscapeLayout();
});
let sheetOpener = null;
function focusables(container){
  return Array.prototype.slice.call(container.querySelectorAll('a[href],button:not([disabled]),[tabindex]:not([tabindex="-1"])'));
}
function trapFocus(e, container){
  const items = focusables(container);
  if (!items.length) return;
  const first = items[0], last = items[items.length - 1];
  if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
  else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
}
function syncSheets(){
  if (!window.matchMedia('(max-width:1180px)').matches) return;
  const any = leftPanel.classList.contains('show') || rightPanel.classList.contains('show');
  document.body.classList.toggle('sheet-open', any);
}
function openSheet(panel, opener){
  sheetOpener = opener || document.activeElement;
  leftPanel.classList.remove('show');
  rightPanel.classList.remove('show');
  panel.classList.add('show');
  syncSheets();
  setTimeout(function(){
    const close = panel.querySelector('.settings-close');
    if (close) close.focus();
  }, 320);
}
function closeSheets(){
  const wasOpen = leftPanel.classList.contains('show') || rightPanel.classList.contains('show');
  leftPanel.classList.remove('show');
  rightPanel.classList.remove('show');
  syncSheets();
  if (wasOpen && sheetOpener && document.contains(sheetOpener)) sheetOpener.focus();
  sheetOpener = null;
}
function currentSheet(){ return leftPanel.classList.contains('show') ? leftPanel : (rightPanel.classList.contains('show') ? rightPanel : null); }
settingsOpen.addEventListener('click', function(e){ openSheet(rightPanel, e.currentTarget); });
settingsClose.addEventListener('click', closeSheets);
chordClose.addEventListener('click', closeSheets);
mChordOpen.addEventListener('click', function(e){ openSheet(leftPanel, e.currentTarget); });
mSetOpen.addEventListener('click', function(e){ openSheet(rightPanel, e.currentTarget); });
sheetScrim.addEventListener('click', closeSheets);
mPlayBtn.addEventListener('click', function(e){ e.currentTarget.blur(); togglePractice(); });
mLandscapeBtn.addEventListener('click', function(e){
  e.currentTarget.blur();
  enterWebLandscape();
  /* 点击进入沉浸横屏即开始练习：暂停中的接着播，未开始的直接开始 */
  if (state.paused) resume();
  else if (!state.active) start();
});
mLandscapeExit.addEventListener('click', function(e){ e.currentTarget.blur(); exitLandscape(); });
stopRound.addEventListener('click', function(e){
  e.stopPropagation();
  stop();
});
/* 键盘快捷键不劫持已聚焦控件的 Space / Enter；弹层维持焦点范围。 */
document.addEventListener('keydown', function(e){
  if (donateMask.classList.contains('show')) {
    if (e.key === 'Escape') { e.preventDefault(); closeDonate(); }
    else if (e.key === 'Tab') trapFocus(e, donateMask);
    return;
  }
  const sheet = currentSheet();
  if (sheet) {
    if (e.key === 'Escape') { e.preventDefault(); closeSheets(); }
    else if (e.key === 'Tab') trapFocus(e, sheet);
    return;
  }
  if (e.key === 'Escape') {
    if (state.active) { e.preventDefault(); stop(); }
    return;
  }
  const control = e.target && e.target.closest && e.target.closest('button,a,input,select,textarea,[role="button"],[role="switch"],[contenteditable="true"]');
  if (control) return;
  if (e.code === 'Space') { e.preventDefault(); togglePractice(); }
  if (e.code === 'Enter') {
    e.preventDefault();
    if (state.active) stop();
    else togglePractice();
  }
});
/* 桌面端可直接点击播放区暂停或继续。 */
chordBlock.addEventListener('click', function(e){
  if (!state.active || window.matchMedia('(max-width:1180px)').matches) return;
  e.stopPropagation();
  if (state.paused) resume(); else pause();
});
chordList.addEventListener('click', function(e){
  const card = e.target.closest('.chord-card');
  if (card) appendSelect(card.dataset.name);
});
chordList.addEventListener('keydown', function(e){
  if (e.key === 'Enter' || e.key === ' ') {
    const card = e.target.closest('.chord-card');
    if (card) { e.preventDefault(); appendSelect(card.dataset.name); }
  }
});
/* 摘要条 chip：点击移除该次出现（后续序号自动重排） */
sumChips.addEventListener('click', function(e){
  const chip = e.target.closest('.sum-chip');
  if (!chip) return;
  const i = Number(chip.dataset.i);
  if (!isNaN(i) && i >= 0 && i < state.selected.length) {
    state.selected.splice(i, 1);
    renderLeft();
    if (state.active) { refreshFutureRows(); } else { renderStandby(); }
  }
});
sumChips.addEventListener('keydown', function(e){
  if (e.key === 'Enter' || e.key === ' ' || e.key === 'Backspace' || e.key === 'Delete') {
    const chip = e.target.closest('.sum-chip');
    if (chip) { e.preventDefault(); chip.click(); }
  }
});
clearBtn.addEventListener('click', function(e){
  e.currentTarget.blur();
  state.selected = [];
  if (state.active) stop();
  renderLeft();
  renderStandby();
});
bpmUp.addEventListener('click', function(e){
  e.currentTarget.blur();
  state.bpm = Math.min(BPM_MAX, state.bpm + BPM_STEP);
  renderRight();
});
bpmDown.addEventListener('click', function(e){
  e.currentTarget.blur();
  state.bpm = Math.max(BPM_MIN, state.bpm - BPM_STEP);
  renderRight();
});
beatUp.addEventListener('click', function(e){
  e.currentTarget.blur();
  const base = state.pendingBeats === null ? state.beats : state.pendingBeats;
  setBeats(Math.min(BEATS_MAX, base + 1));
});
beatDown.addEventListener('click', function(e){
  e.currentTarget.blur();
  const base = state.pendingBeats === null ? state.beats : state.pendingBeats;
  setBeats(Math.max(BEATS_MIN, base - 1));
});
multiSwitch.addEventListener('click', function(e){
  e.currentTarget.blur();
  state.multi = !state.multi;
  renderRight();
  renderLeft();
});
hideListSwitch.addEventListener('click', function(e){
  e.currentTarget.blur();
  state.autoHideList = !state.autoHideList;
  renderRight();
  if (state.active) applyPanelAutoHide(true);
});
hideSetSwitch.addEventListener('click', function(e){
  e.currentTarget.blur();
  state.autoHideSet = !state.autoHideSet;
  renderRight();
  if (state.active) applyPanelAutoHide(true);
});
previewSwitch.addEventListener('click', function(e){
  e.currentTarget.blur();
  state.preview = !state.preview;
  renderRight();   /* 只切换下次发声方式（扫弦声 / 节拍器），画面与拍点不变 */
});
randomSwitch.addEventListener('click', function(e){
  e.currentTarget.blur();
  state.random = !state.random;
  renderRight();
  if (state.active) {
    refreshFutureRows();   /* 后续行即时按新模式重排 */
  } else {
    renderStandby();
  }
});

/* ===================== 初始化 ===================== */
renderLeft();
renderRight();
updateMobilePlayBtn();
renderStandby();
})();
